/**
 * @file ucl_parser.c
 * The implementation of ucl parser
 */

struct ucl_parser_saved_state {
        unsigned int line;
        unsigned int column;
        size_t remain;
        const unsigned char *pos;
};

/**
 * Move up to len characters
 * @param parser
 * @param begin
 * @param len
 * @return new position in chunk
 */
#define ucl_chunk_skipc(chunk, p)    \
do {                                 \
        if (*(p) == '\n') {          \
                (chunk)->line ++;    \
                (chunk)->column = 0; \
        }                            \
        else (chunk)->column ++;     \
        (p++);                       \
        (chunk)->pos ++;             \
        (chunk)->remain --;          \
} while (0)

